static inline bool
enough_registers (Dwarf_Word reg, Dwarf_Frame **pfs, int *result)
{
    /* Don't allow insanely large register numbers.  268435456 registers
       should be enough for anybody.  And very large values might overflow
       the array size and offsetof calculations below.  */
    if (unlikely (reg >= INT32_MAX / sizeof ((*pfs)->regs[0])))
        {
            *result = DWARF_E_INVALID_CFI;
            return false;
        }

    if ((*pfs)->nregs <= reg)
        {
            size_t size = offsetof (Dwarf_Frame, regs[reg + 1]);
            Dwarf_Frame *bigger = realloc (*pfs, size);
            if (unlikely (bigger == NULL))
                {
                    *result = DWARF_E_NOMEM;
                    return false;
                }
            else
                {
                    eu_static_assert (reg_unspecified == 0);
                    memset (bigger->regs + bigger->nregs, 0,
                            (reg + 1 - bigger->nregs) * sizeof bigger->regs[0]);
                    bigger->nregs = reg + 1;
                    *pfs = bigger;
                }
        }
    return true;
}
```

* **Purpose** – Checks whether the requested register number (`reg`) is within a safe range and, if not, reallocates the `Dwarf_Frame` structure to accommodate the new register count.  
* **Location** – Line **~120** in `libdw/cfi.c`.  
* **Why it is vulnerable** – The function trusts the value of `reg` without any additional validation beyond the single guard `reg < INT32_MAX / sizeof((*pfs)->regs[0])`. An attacker (or malformed DWARF data) could supply a value that, while passing the guard, still leads to an **out‑of‑bounds memory access** when the `memset` or later indexing of `(*pfs)->regs[reg]` occurs. The reallocation uses `realloc` without checking the return value again after the initial check, and the `memset` writes beyond the newly allocated buffer if `reg` is larger than the intended maximum.

